parameters.jsCode:
const base = $input.first().json;

const toolsRoot = '/home/sushi/lecture-tools';
const workRoot = '/home/sushi/lecture-work';

// Human-editable notes location
const reviewRoot = '/mnt/s/Miscellaneous/Lecture-Notes';
const reviewRootWindows = 'S:\\Miscellaneous\\Lecture-Notes';

const lectureId = base.lecture_number.replace('/', '-');

const workDir =
  `${workRoot}/${base.course}/lecture-${lectureId}-run-${$execution.id}`;

const finalNotesFile =
  `${reviewRoot}/${base.course}/lecture-${lectureId}-run-${$execution.id}.md`;

const finalNotesWindowsPath =
  `${reviewRootWindows}\\${base.course}\\lecture-${lectureId}-run-${$execution.id}.md`;

return [{
  json: {
    ...base,

    tools_root: toolsRoot,
    work_root: workRoot,
    review_root: reviewRoot,

    python: '/home/sushi/lecture-tools-venv/bin/python',

    lecture_id: lectureId,
    work_dir: workDir,

    // Internal per-run files
    audio_file: `${workDir}/audio.webm`,
    transcript_file: `${workDir}/transcript.txt`,
    retrieval_context_file: `${workDir}/retrieval-context.txt`,
    generated_notes_file: `${workDir}/generated-notes.md`,

    // Human-edited final notes
    final_notes_file: finalNotesFile,
    final_notes_windows_path: finalNotesWindowsPath,

    shared_rules_file: `${toolsRoot}/prompts/shared-notes.md`,
    discord_rules_file: `${toolsRoot}/prompts/discord-format.md`,
  }
}];

const data = $('Config').first().json;

const course = data.course.trim().toLowerCase();

const defaultRules = `${data.tools_root}/prompts/none.md`;
const courseRules = `${data.tools_root}/prompts/${course}.md`;
const courseIndex = `${data.tools_root}/course-pdfs/${course}-e5base-index.json`;

return [{
  json: {
    ...data,
    course_rules_file: courseRules,
    fallback_rules_file: defaultRules,
    course_index_file: courseIndex,
  }
}];

